import {layerColors,shiftLayer,belongsToLayer,layerVisible} from './elevation-schema.js?v=87ae808bfa10375d';
import {rampPlan,elevationWarnings} from './elevation.js?v=87ae808bfa10375d';
import {boardPath,containsPoint,boardOutline} from './board.js?v=87ae808bfa10375d';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {uid} from './ids.js?v=87ae808bfa10375d';
export class LevelsUI{
 constructor(api){this.api=api;this.other=true;this.terrainId=null;this.mode='2d';this.pendingTerrain=false;
  $('#view-2d').onclick=()=>this.setView('2d');$('#view-3d').onclick=()=>this.setView('3d');
  $('#level-quick').onchange=e=>this.activate(e.target.value);
  $('#other-levels').onchange=e=>{this.other=e.target.checked;api.redraw();};
  $('#terrain-xray').onclick=()=>{const b=$('#terrain-xray'),next=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(next));this.viewer?.xray(next);};
  document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>this.viewer?.preset(b.dataset.camera));
 }
 current(){const p=this.api.project();return p.layers.find(l=>l.id===p.activeLayerId)||p.layers[0];}
 editable(p){return belongsToLayer(p,this.current().id)&&this.current().visible;}
 visible(p){return layerVisible(p,this.api.project().layers)&&(this.mode==='3d'||this.other||this.editable(p));}
 activate(id){this.api.clear();this.api.commit(p=>{p.activeLayerId=id;p.layers.find(l=>l.id===id).visible=true;});}
 async setView(mode){this.pendingTerrain=false;this.api.clear();this.mode=mode;const three=mode==='3d';this.api.view(three);$('#canvas-wrap').classList.toggle('is-3d',three);$('#viewer3d').hidden=!three;$('#view-2d').classList.toggle('active',!three);$('#view-3d').classList.toggle('active',three);$('#camera-tools').hidden=!three;$('#other-levels').disabled=three;this.api.refresh();
  if(three){$('#viewer-message').textContent='正在准备立体沙盘…';try{if(!this.viewer){const {createViewer}=await (this.load??=import('./viewer3d.js?v=87ae808bfa10375d'));if(this.mode!=='3d')return;if(!this.viewer)this.viewer=createViewer($('#viewer3d'),message=>{$('#viewer-message').textContent=message;});}if(this.mode!=='3d')return;this.viewer.update(this.api.project(),this.api.byId());this.viewer.xray($('#terrain-xray').getAttribute('aria-pressed')==='true');this.viewer.resize();this.viewer.preset('iso');$('#viewer-message').textContent='拖动旋转 · 滚轮缩放 · 右键平移 · 返回 2D 编辑';}catch(e){$('#viewer-message').textContent='3D 无法启动，请启用浏览器硬件加速，或返回 2D 继续设计。';console.error(e);}}
  else this.api.redraw();
 }
 render(){const p=this.api.project(),l=this.current(),selection=this.api.selected();
  $('#level-quick').innerHTML=p.layers.map(x=>`<option value="${esc(x.id)}" ${x.id===l.id?'selected':''}>${esc(x.name)} · ${x.height} mm</option>`).join('');
  $('#levels-panel').innerHTML=`<div class="section-heading"><h2>楼层与高架</h2><button id="level-add" class="text-btn">＋ 新楼层</button></div><p class="shape-note">跨层坡道在两层共享显示与编辑，不重复计入零件清单。高度以地面 0 mm 为基准。</p><div class="level-list">${p.layers.map(x=>`<div class="level-row ${x.id===l.id?'active':''}"><button data-level="${esc(x.id)}"><i style="background:${x.color}"></i><span>${esc(x.name)}<small>${x.height} mm · ${p.pieces.filter(q=>belongsToLayer(q,x.id)).length} 个零件</small></span></button><input data-visible="${esc(x.id)}" type="checkbox" ${x.visible?'checked':''} aria-label="显示 ${esc(x.name)}" title="显示 / 隐藏此层"></div>`).join('')}</div><div class="two-fields"><label>当前层名称<input id="level-name" maxlength="60" value="${esc(l.name)}"></label><label>高度 / mm<input id="level-height" type="number" min="-10000" max="10000" value="${l.height}"></label></div><div class="level-actions"><label>楼层颜色 <input id="level-color" type="color" value="${l.color}"></label><button id="level-delete" class="text-btn" ${p.layers.length===1?'disabled':''}>删除空层</button></div><label class="field">将所选 ${selection.length} 个零件移至<select id="selection-layer" ${selection.length?'':'disabled'}><option value="">选择目标楼层…</option>${p.layers.filter(x=>x.id!==l.id).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${x.height} mm</option>`).join('')}</select></label><button id="ramp-open" class="full-btn" ${selection.length?'':'disabled'}>连接楼层 · 创建坡道 ↗</button><p class="shape-note">支持所有可放置轨道，含复线、道岔、交叉轨和转盘。坡道在起始层和目标层均可接轨。</p>`;
  $('#level-add').onclick=()=>{if(p.layers.length>=32)return this.api.toast('最多 32 个楼层');this.api.clear();this.api.commit(p=>{const id=uid();p.layers.push({id,name:'高架层 '+p.layers.length,height:Math.min(10000,l.height+60),color:layerColors[p.layers.length%layerColors.length],visible:true});p.activeLayerId=id;});};
  document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>this.activate(b.dataset.level));
  document.querySelectorAll('[data-visible]').forEach(b=>b.onchange=()=>{const checked=b.checked;if(b.dataset.visible===p.activeLayerId)this.api.clear();this.api.commit(p=>p.layers.find(l=>l.id===b.dataset.visible).visible=checked);});
  $('#level-name').onchange=e=>{const name=e.target.value.trim();if(!name){this.render();return;}this.api.commit(()=>l.name=name);};
  $('#level-height').onchange=e=>{const h=Number(e.target.value);if(!Number.isFinite(h)||Math.abs(h)>10000){this.api.toast('楼层高度应在 −10000 到 10000 mm');this.render();return;}const trial=structuredClone(p);shiftLayer(trial,l.id,h);if(trial.pieces.some(q=>Math.abs(q.z)>10000||Math.abs(q.zEnd)>10000)){this.api.toast('部分轨道高度将超出允许范围');this.render();return;}this.api.commit(p=>shiftLayer(p,l.id,h));};
  $('#level-color').onchange=e=>{const color=e.target.value;this.api.commit(()=>l.color=color);};
  $('#level-delete').onclick=()=>{if(p.pieces.some(q=>q.layerId===l.id||q.endLayerId===l.id||q.ramp?.from===l.id||q.ramp?.to===l.id))return this.api.toast('此层仍有零件或坡道引用，请先移动或删除它们');this.api.clear();this.api.commit(p=>{p.layers=p.layers.filter(x=>x.id!==l.id);p.activeLayerId=p.layers[0].id;});};
  $('#selection-layer').onchange=e=>{const target=p.layers.find(x=>x.id===e.target.value);if(!target)return;if(selection.some(q=>{const delta=target.height-p.layers.find(x=>x.id===q.layerId).height;return Math.abs(q.z+delta)>10000||Math.abs(q.zEnd+delta)>10000;})){this.api.toast('移动后部分轨道高度将超出范围');this.render();return;}this.api.clear();this.api.commit(p=>{for(const q of selection){const dz=target.height-p.layers.find(x=>x.id===q.layerId).height;q.z+=dz;q.zEnd+=dz;q.layerId=target.id;delete q.endLayerId;delete q.ramp;}p.activeLayerId=target.id;target.visible=true;});};
  $('#ramp-open').onclick=()=>this.ramp();this.renderTerrain();
  $('#elevation-limits').innerHTML=`<div class="two-fields"><label>提醒坡度 / %<input id="limit-grade" type="number" min="0.1" max="20" step="0.1" value="${p.designLimits.maxGrade}"></label><label>交叉高度差 / mm<input id="limit-clearance" type="number" min="1" max="1000" value="${p.designLimits.clearance}"></label></div><p class="shape-note">高度差检查针对轨道中心线交叉；不等同于车体、桥梁或隧道净空验证。</p>`;
  for(const [id,key,min,max] of [['grade','maxGrade',.1,20],['clearance','clearance',1,1000]])$('#limit-'+id).onchange=e=>{const n=Number(e.target.value);if(!Number.isFinite(n)||n<min||n>max){this.render();return;}this.api.commit(p=>p.designLimits[key]=n);};
  if(this.mode==='3d'&&this.viewer){this.viewer.update(p,this.api.byId());}
 }
 warnings(){const p=this.api.project(),key=JSON.stringify([p.pieces,p.terrain,p.designLimits]);if(key!==this.warningKey){this.warningKey=key;this.warningValue=elevationWarnings(p,this.api.byId());}return this.warningValue;}
 terrainMarkup(){const p=this.api.project();return `<defs><clipPath id="terrain-clip"><path d="${boardPath(p.board)}"/></clipPath></defs><g clip-path="url(#terrain-clip)" pointer-events="none">${p.terrain.map(t=>`<g>${[1,.8,.6,.4,.2].map((f,i)=>`<ellipse cx="${t.x}" cy="${t.y}" rx="${t.rx*f}" ry="${t.ry*f}" fill="${t.type==='valley'?'#739aa9':'#8fae75'}" fill-opacity=".12" stroke="${t.type==='valley'?'#507f93':'#718d60'}" stroke-opacity=".35" stroke-width="1" vector-effect="non-scaling-stroke"/>`).join('')}<text x="${t.x}" y="${t.y}" text-anchor="middle" fill="#44614f" font-size="14">${esc(t.name)} · ${t.height>0?'+':''}${t.height} mm</text></g>`).join('')}</g>`;}
 renderTerrain(){const p=this.api.project();if(!p.terrain.some(t=>t.id===this.terrainId))this.terrainId=p.terrain[0]?.id;const t=p.terrain.find(t=>t.id===this.terrainId);
  $('#terrain-panel').innerHTML=`<div class="section-heading"><h2>地形塑造</h2><span class="badge">${p.terrain.length} 个区域</span></div><p class="shape-note">点击画布添加，再调整中心、范围与高度。区域重叠时高度相加，边缘自动过渡。</p><div class="terrain-buttons"><button data-terrain="hill">＋ 山丘</button><button data-terrain="plateau">＋ 台地</button><button data-terrain="valley">＋ 谷地</button></div>${t?`<label class="field">编辑区域<select id="terrain-select">${p.terrain.map(x=>`<option value="${esc(x.id)}" ${x===t?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><div class="two-fields">${[['name','名称','text'],['height','中心高度 / mm','number'],['x','中心 X / mm','number'],['y','中心 Y / mm','number'],['rx','X 半径 / mm','number'],['ry','Y 半径 / mm','number']].map(([key,label,type])=>`<label>${label}<input id="terrain-${key}" type="${type}" value="${esc(t[key])}" ${type==='text'?'maxlength="60"':''}></label>`).join('')}</div><button id="terrain-remove" class="text-btn">删除此地形</button>`:'<p class="shape-note">尚未添加地形 · 默认平整地面</p>'}`;
  document.querySelectorAll('[data-terrain]').forEach(b=>b.onclick=()=>{if(p.terrain.length>=100)return this.api.toast('最多 100 个地形区域');this.setView('2d');this.pendingTerrain=b.dataset.terrain;this.api.toast('点击沙盘内部放置地形；Esc 取消');$('#canvas-hint').textContent='点击沙盘内部放置地形 · Esc 取消';});
  if(!t)return;$('#terrain-select').onchange=e=>{this.terrainId=e.target.value;this.renderTerrain();};$('#terrain-remove').onclick=()=>this.api.commit(p=>p.terrain=p.terrain.filter(x=>x!==t));
  for(const key of ['name','height','x','y','rx','ry'])$('#terrain-'+key).onchange=e=>{let value=key==='name'?e.target.value.trim():Number(e.target.value);const limits={height:[t.type==='valley'?-1000:0,t.type==='valley'?0:3000],x:[0,p.board.width],y:[0,p.board.height],rx:[10,50000],ry:[10,50000]};if(key==='name'?!value:(!Number.isFinite(value)||value<limits[key][0]||value>limits[key][1])){this.api.toast('请输入有效范围内的地形参数');this.renderTerrain();return;}this.api.commit(()=>t[key]=value);};
 }
 placeTerrain(at){if(!this.pendingTerrain)return false;const p=this.api.project();if(!containsPoint(at,boardOutline(p.board))){this.api.toast('请在沙盘轮廓内部点击');return true;}const type=this.pendingTerrain,id=uid();this.pendingTerrain=false;this.terrainId=id;this.api.commit(p=>p.terrain.push({id,type,name:{hill:'山丘',plateau:'台地',valley:'谷地'}[type]+' '+(p.terrain.length+1),x:Math.round(at.x),y:Math.round(at.y),rx:Math.max(10,Math.round(p.board.width/7)),ry:Math.max(10,Math.round(p.board.height/5)),height:type==='valley'?-30:60}));return true;}
 ramp(){const p=this.api.project(),chosen=this.api.selected();if(p.layers.length<2)return this.api.toast('请先新建一个不同高度的楼层');const options=p.layers.map(l=>`<option value="${esc(l.id)}">${esc(l.name)} · ${l.height} mm</option>`).join('');this.api.modal('连接楼层 · 坡道设计',`<p>选中 ${chosen.length} 个零件。连续单线、复线沿线路爬升；分支、交叉和闭环自动采用方向坡面，保证相同位置高度一致。建筑、飞机与机场设施保持原状。</p><div class="two-fields"><label>起始楼层<select id="ramp-from">${options}</select></label><label>目标楼层<select id="ramp-to">${options}</select></label></div><div class="two-fields"><label>计算方式<select id="ramp-mode"><option value="auto">自动适配轨道</option><option value="plane">按方向形成坡面</option></select></label><label>坡面方向 / °<input id="ramp-angle" type="number" min="-360" max="360" step="1" placeholder="自动识别" disabled></label></div><label class="check-row"><input id="ramp-reverse" type="checkbox">交换 A / B 高度方向</label><div id="ramp-preview" role="status"></div><p class="shape-note">预览中的 A、B 标记同时显示在画布。应用后调整楼层高度，坡道会随之更新。沿线路模式按路径长度分配高度；方向坡面按空间位置分配，支线和闭环可能有上坡、下坡及平坡。坡顶、坡脚缓和段需另行安排。</p><button id="ramp-apply" class="full-btn primary">应用坡道</button>`);$('#ramp-from').value=this.current().id;$('#ramp-to').value=p.layers.find(l=>l.id!==this.current().id).id;let plan;
  const preview=()=>{plan=null;this.rampMarkers=null;try{const a=p.layers.find(l=>l.id===$('#ramp-from').value),b=p.layers.find(l=>l.id===$('#ramp-to').value);if(a.id===b.id||a.height===b.height)throw Error('请选择两个不同高度的楼层');plan=rampPlan(chosen,this.api.byId(),a.height,b.height,$('#ramp-reverse').checked,{mode:$('#ramp-mode').value,angle:$('#ramp-mode').value==='plane'&&$('#ramp-angle').value!==''?Number($('#ramp-angle').value):undefined});this.rampMarkers=[plan.start,plan.end];const up=b.height>=a.height;$('#ramp-preview').innerHTML=`<div class="ramp-metrics"><strong>${plan.grade.toFixed(2)}%<small>最大轨道坡度</small></strong><span>${Math.round(plan.length)} mm ${plan.mode==='plane'?'方向跨度':'参考路径'}<br>${Math.abs(b.height-a.height)} mm 高差</span></div><p class="shape-note">${plan.mode==='plane'?'方向坡面 · '+plan.angle.toFixed(1)+'° · 全部分支在同一坡面内，可选择方向模式修改角度。':'沿线路爬升 · 复线在对应断面采用相同高度，内外轨实际坡度可能不同。'}${plan.ignored?' 已跳过 '+plan.ignored+' 个非轨道零件。':''}</p><svg class="ramp-profile" viewBox="0 0 460 125" role="img" aria-label="坡道高程剖面"><path d="M35 95H425" stroke="#cbd6cc"/><path d="M35 ${up?95:30}L425 ${up?30:95}V110H35Z" fill="#e0ece1"/><path d="M35 ${up?95:30}L425 ${up?30:95}" stroke="#426f59" stroke-width="3"/><text x="35" y="18">A · ${a.height} mm</text><text x="425" y="18" text-anchor="end">B · ${b.height} mm</text></svg><p class="${plan.grade>p.designLimits.maxGrade?'warnings':'shape-note'}">${plan.grade>p.designLimits.maxGrade?'△ 超过设定的 '+p.designLimits.maxGrade+'%，建议延长线路。':'坡度未超过设定阈值。'} 按 ${p.designLimits.maxGrade}%，至少需要 ${Math.ceil(Math.abs(b.height-a.height)/p.designLimits.maxGrade*100)} mm 路径。</p>`;$('#ramp-apply').disabled=false;}catch(e){$('#ramp-preview').textContent=e.message;$('#ramp-apply').disabled=true;}this.api.redraw();};
  for(const id of ['ramp-from','ramp-to','ramp-reverse','ramp-angle'])$('#'+id).onchange=preview;$('#ramp-mode').onchange=()=>{$('#ramp-angle').disabled=$('#ramp-mode').value!=='plane';preview();};
  $('#ramp-apply').onclick=()=>{if(!plan)return;const from=$('#ramp-from').value,to=$('#ramp-to').value,a=p.layers.find(l=>l.id===from).height,b=p.layers.find(l=>l.id===to).height;this.rampMarkers=null;this.api.clear();this.api.commit(p=>{for(const q of plan.pieces){const live=p.pieces.find(x=>x.id===q.id);Object.assign(live,{z:q.z,zEnd:q.zEnd,layerId:from,ramp:{from,to,t0:Math.max(0,Math.min(1,(q.z-a)/(b-a))),t1:Math.max(0,Math.min(1,(q.zEnd-a)/(b-a)))}});if(q.slope)live.slope={...q.slope};else delete live.slope;delete live.endLayerId;}p.activeLayerId=to;p.layers.find(l=>l.id===from).visible=true;p.layers.find(l=>l.id===to).visible=true;});$('#modal').close();this.api.toast('已切换至目标层，可从坡道对应高度的端点继续接轨');};
  $('#modal').addEventListener('close',()=>{this.rampMarkers=null;this.api.redraw();},{once:true});preview();
 }
}
